  if (total === 1) return [1];

  const current = Math.min(Math.max(1, currentPage), total);
  const maxWithoutEllipsis = siblingCount * 2 + 5; // first, last, current, 2 ellipses, siblings

  if (total <= maxWithoutEllipsis) return range(1, total);

  const left = Math.max(current - siblingCount, 2);
  const right = Math.min(current + siblingCount, total - 1);
  const showLeftEllipsis = left > 2;
  const showRightEllipsis = right < total - 1;

  return [
    1,
    ...(showLeftEllipsis ? [ELLIPSIS] : range(2, left - 1)),
    ...range(left, right),
    ...(showRightEllipsis ? [ELLIPSIS] : range(right + 1, total - 1)),
    total,
  ];
}

export function Pagination({
  totalPages,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
