type PageItem = number | typeof ELLIPSIS;

const range = (start: number, end: number): number[] =>
  Array.from({ length: Math.max(0, end - start + 1) }, (_, i) => start + i);

/** Builds the list of page items, e.g. [1, "…", 4, 5, 6, "…", 20]. */
export function getPageItems(
  totalPages: number,
  currentPage: number,
  siblingCount = 1
): PageItem[] {
  // Exactly one page (or zero results): show 1 through 1.
  if (totalPages <= 1) return [1];

  // Few enough pages to show them all.
  const maxVisible = siblingCount * 2 + 5; // first, last, current, 2 ellipses
  if (totalPages <= maxVisible) return range(1, totalPages);

  const left = Math.max(currentPage - siblingCount, 1);
  const right = Math.min(currentPage + siblingCount, totalPages);
  const showLeftEllipsis = left > 2;
  const showRightEllipsis = right < totalPages - 1;
  const edgeCount = siblingCount * 2 + 3;

  if (!showLeftEllipsis && showRightEllipsis) {
    return [...range(1, edgeCount), ELLIPSIS, totalPages];
  }
  if (showLeftEllipsis && !showRightEllipsis) {
    return [1, ELLIPSIS, ...range(totalPages - edgeCount + 1, totalPages)];
  }
  return [1, ELLIPSIS, ...range(left, right), ELLIPSIS, totalPages];
}

