```tsx
// Pagination.tsx
import React from "react";

export function getPageRange(
  currentPage: number,
  totalPages: number,
  siblings = 1
): (number | "…")[] {
  const total = Math.max(1, Math.floor(totalPages));

  // Exactly one page: show just [1]
  if (total === 1) return [1];

  const current = Math.min(Math.max(1, currentPage), total);
  const maxVisible = siblings * 2 + 5; // first, last, current, 2 ellipses, siblings

  if (total <= maxVisible) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }

  const left = Math.max(current - siblings, 2);
  const right = Math.min(current + siblings, total - 1);
  const showLeftEllipsis = left > 2;
  const showRightEllipsis = right < total - 1;

  const pages: (number | "…")[] = [1];
  if (showLeftEllipsis) pages.push("…");
  for (let p = left; p <= right; p++) pages.push(p);
  if (showRightEllipsis) pages.push("…");
  pages.push(total);
  return pages;
}

interface PaginationProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  siblings?: number;
}

export function Pagination({
  currentPage,
  totalPages,
  onPageChange,
  siblings = 1,
}: PaginationProps) {
  const total = Math.max(1, Math.floor(totalPages));
  const current = Math.min(Math.max(1, currentPage), total);
  const pages = getPageRange(current, total, siblings);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(current - 1)}
            disabled={current <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {pages.map((p, i) =>
          p === "…" ? (
            <li key={`ellipsis-${i}`} aria-hidden="true">…</li>
          ) : (
            <li key={p}>
              <button
                onClick={() => onPageChange(p)}
                aria-current={p === current ? "page" : undefined}
                disabled={p === current}
              >
                {p}
              </button>
            </li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(current + 1)}
            disabled={current >= total}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
